import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import "../css/homepage.css";
import "../css/review.css";

const API_BASE_URL = "http://localhost:5001";
const PAGE_SIZE = 6;

export default function Review() {
  const navigate = useNavigate();

  const [user, setUser] = useState(null);
  const [token, setToken] = useState("");
  const [rooms, setRooms] = useState([]);
  const [reviews, setReviews] = useState([]);
  const [selectedRoomId, setSelectedRoomId] = useState("");

  const [usageCount, setUsageCount] = useState(null);
  const [loading, setLoading] = useState(false);
  const [statusMessage, setStatusMessage] = useState("");

  const [search, setSearch] = useState("");
  const [ratingFilter, setRatingFilter] = useState("all");
  const [sort, setSort] = useState("newest");
  const [visibleCount, setVisibleCount] = useState(PAGE_SIZE);

  const [modalOpen, setModalOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState("review");
  const [formRoomId, setFormRoomId] = useState("");
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState("");
  const [formMessage, setFormMessage] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const [profileOpen, setProfileOpen] = useState(false);

  // ----------------------------------------
  // SESSION
  // ----------------------------------------

  useEffect(() => {
    try {
      const storedUser = JSON.parse(
        localStorage.getItem("user") || "null"
      );

      if (!storedUser) {
        navigate("/");
        return;
      }

      setUser(storedUser);
      setToken(localStorage.getItem("token") || "");
    } catch (error) {
      console.error("Unable to read user session:", error);
      navigate("/");
    }
  }, [navigate]);

  // ----------------------------------------
  // API HELPERS
  // ----------------------------------------

  function authHeaders(includeJson = false) {
    const headers = {};

    if (includeJson) {
      headers["Content-Type"] = "application/json";
    }

    if (token) {
      headers.Authorization = `Bearer ${token}`;
    }

    const userId = user?.user_id ?? user?.id;

    if (userId != null) {
      headers["x-user-id"] = String(userId);
    }

    return headers;
  }

  async function apiFetch(path, options = {}) {
    const response = await fetch(`${API_BASE_URL}${path}`, {
      ...options,
      headers: {
        ...authHeaders(Boolean(options.body)),
        ...(options.headers || {}),
      },
    });

    const contentType = response.headers.get("content-type") || "";

    const payload = contentType.includes("application/json")
      ? await response.json()
      : await response.text();

    if (!response.ok) {
      throw new Error(
        payload?.message ||
          (typeof payload === "string" && payload) ||
          `Request failed (${response.status})`
      );
    }

    return payload;
  }

  function getArray(payload, key) {
    if (Array.isArray(payload)) return payload;
    if (Array.isArray(payload?.[key])) return payload[key];
    if (Array.isArray(payload?.data)) return payload.data;
    return [];
  }

  function normalizeRoom(room) {
    const id = room.room_id ?? room.id ?? room.id_room ?? "";

    const name =
      room.room_name ??
      room.name ??
      room.roomName ??
      `ห้อง ${id}`;

    const number = room.room_number ?? room.room_no ?? "";

    const label =
      number && !String(name).includes(String(number))
        ? `${number} ${name}`
        : String(name);

    return {
      id: String(id),
      name: label,
    };
  }

  function normalizeReview(review) {
    return {
      id: review.review_id ?? review.id ?? "",
      roomId: String(review.room_id ?? ""),
      name:
        review.displayname_th ||
        review.displayname_en ||
        review.username ||
        review.name ||
        "ผู้ใช้งาน",
      date: review.created_at || review.date || "",
      rating: Number(review.rating || 0),
      message: review.comment ?? review.message ?? "",
      type: review.feedback_type || review.type || "review",
    };
  }

  // ----------------------------------------
  // LOAD ROOMS
  // ----------------------------------------

  useEffect(() => {
    if (!user) return;

    let cancelled = false;

    async function loadRooms() {
      setLoading(true);
      setStatusMessage("กำลังโหลดรายชื่อห้อง...");

      try {
        const payload = await apiFetch("/api/rooms");
        const data = getArray(payload, "rooms");

        const normalized = data
          .map(normalizeRoom)
          .filter((room) => room.id !== "");

        if (cancelled) return;

        setRooms(normalized);

        setSelectedRoomId((current) => {
          if (normalized.some((room) => room.id === current)) {
            return current;
          }
          return normalized[0]?.id || "";
        });

        setFormRoomId((current) => {
          if (normalized.some((room) => room.id === current)) {
            return current;
          }
          return normalized[0]?.id || "";
        });

        setStatusMessage(
          normalized.length
            ? ""
            : "ไม่พบข้อมูลห้องจาก API /api/rooms"
        );
      } catch (error) {
        if (cancelled) return;

        setRooms([]);
        setStatusMessage(
          `โหลดรายชื่อห้องไม่สำเร็จ: ${error.message}`
        );
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    loadRooms();

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user, token]);

  // ----------------------------------------
  // LOAD REVIEWS AND ROOM USAGE
  // ----------------------------------------

  useEffect(() => {
    if (!user || !selectedRoomId) {
      setReviews([]);
      setUsageCount(null);
      return;
    }

    let cancelled = false;

    async function loadRoomData() {
      setLoading(true);
      setStatusMessage("กำลังโหลดรีวิวและสถิติการใช้งาน...");

      const [reviewResult, usageResult] = await Promise.allSettled([
        apiFetch(
          `/api/reviews?room_id=${encodeURIComponent(selectedRoomId)}`
        ),
        apiFetch(
          `/api/rooms/usage?room_id=${encodeURIComponent(selectedRoomId)}`
        ),
      ]);

      if (cancelled) return;

      const errors = [];

      if (reviewResult.status === "fulfilled") {
        const data = getArray(reviewResult.value, "reviews");
        setReviews(data.map(normalizeReview));
      } else {
        setReviews([]);
        errors.push(
          `โหลดรีวิวไม่สำเร็จ: ${reviewResult.reason?.message || "เกิดข้อผิดพลาด"}`
        );
      }

      if (usageResult.status === "fulfilled") {
        const payload = usageResult.value;

        const count =
          typeof payload === "number"
            ? payload
            : typeof payload === "string"
              ? Number(payload)
              : Number(
                  payload?.usage_count ??
                    payload?.count ??
                    payload?.total ??
                    payload?.data?.usage_count ??
                    0
                );

        setUsageCount(Number.isFinite(count) ? Math.max(0, count) : null);
      } else {
        setUsageCount(null);
        errors.push(
          `โหลดจำนวนการใช้งานไม่สำเร็จ: ${usageResult.reason?.message || "เกิดข้อผิดพลาด"}`
        );
      }

      setStatusMessage(errors.join(" | "));
      setLoading(false);
    }

    loadRoomData();

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedRoomId, user, token]);

  // ----------------------------------------
  // STATISTICS
  // ----------------------------------------

  const validRatings = useMemo(
    () =>
      reviews.filter(
        (review) => review.rating >= 1 && review.rating <= 5
      ),
    [reviews]
  );

  const averageRating = useMemo(() => {
    if (!validRatings.length) return null;

    return (
      validRatings.reduce((sum, review) => sum + review.rating, 0) /
      validRatings.length
    );
  }, [validRatings]);

  const selectedRoom = rooms.find(
    (room) => room.id === selectedRoomId
  );

  // ----------------------------------------
  // FILTER AND SORT
  // ----------------------------------------

  const filteredReviews = useMemo(() => {
    const result = reviews.filter((review) => {
      const text =
        `${review.name} ${review.message}`.toLowerCase();

      const matchesSearch = text.includes(search.trim().toLowerCase());

      const matchesRating =
        ratingFilter === "all" ||
        String(review.rating) === ratingFilter;

      return matchesSearch && matchesRating;
    });

    result.sort((a, b) => {
      const dateA = new Date(a.date || 0).getTime() || 0;
      const dateB = new Date(b.date || 0).getTime() || 0;

      if (sort === "highest") {
        return b.rating - a.rating || dateB - dateA;
      }

      if (sort === "lowest") {
        return a.rating - b.rating || dateB - dateA;
      }

      return dateB - dateA;
    });

    return result;
  }, [reviews, search, ratingFilter, sort]);

  const visibleReviews = filteredReviews.slice(0, visibleCount);

  // ----------------------------------------
  // REFRESH
  // ----------------------------------------

  async function refreshData() {
    if (!selectedRoomId) {
      setStatusMessage("กรุณาเลือกห้องก่อน");
      return;
    }

    setLoading(true);
    setStatusMessage("กำลังโหลดข้อมูลใหม่...");

    const [reviewResult, usageResult] = await Promise.allSettled([
      apiFetch(
        `/api/reviews?room_id=${encodeURIComponent(selectedRoomId)}`
      ),
      apiFetch(
        `/api/rooms/usage?room_id=${encodeURIComponent(selectedRoomId)}`
      ),
    ]);

    const errors = [];

    if (reviewResult.status === "fulfilled") {
      setReviews(
        getArray(reviewResult.value, "reviews").map(normalizeReview)
      );
    } else {
      errors.push(`โหลดรีวิวไม่สำเร็จ: ${reviewResult.reason?.message}`);
    }

    if (usageResult.status === "fulfilled") {
      const payload = usageResult.value;
      const count =
        typeof payload === "number"
          ? payload
          : Number(
              payload?.usage_count ??
                payload?.count ??
                payload?.total ??
                payload?.data?.usage_count ??
                0
            );

      setUsageCount(Number.isFinite(count) ? Math.max(0, count) : null);
    } else {
      setUsageCount(null);
      errors.push(
        `โหลดจำนวนการใช้งานไม่สำเร็จ: ${usageResult.reason?.message}`
      );
    }

    setStatusMessage(errors.join(" | "));
    setLoading(false);
  }

  // ----------------------------------------
  // REVIEW MODAL
  // ----------------------------------------

  function openModal(type) {
    setFeedbackType(type);
    setFormRoomId(selectedRoomId || rooms[0]?.id || "");
    setRating(0);
    setComment("");
    setFormMessage("");
    setModalOpen(true);
  }

  function closeModal() {
    if (submitting) return;
    setModalOpen(false);
  }

  async function submitReview(event) {
    event.preventDefault();
    setFormMessage("");

    if (!user) {
      setFormMessage("กรุณาเข้าสู่ระบบก่อนส่งความคิดเห็น");
      return;
    }

    const userId = user.user_id ?? user.id;
    const message = comment.trim();

    if (!formRoomId) {
      setFormMessage("กรุณาเลือกห้อง");
      return;
    }

    if (!message) {
      setFormMessage("กรุณากรอกรายละเอียดความคิดเห็น");
      return;
    }

    if (feedbackType === "review" && !rating) {
      setFormMessage("กรุณาเลือกคะแนนรีวิว 1–5 ดาว");
      return;
    }

    if (userId == null) {
      setFormMessage("ไม่พบรหัสผู้ใช้ กรุณาเข้าสู่ระบบใหม่");
      return;
    }

    const payload = {
      room_id: Number(formRoomId),
      user_id: userId,
      rating: feedbackType === "review" ? rating : null,
      feedback_type: feedbackType,
      comment: message,
    };

    setSubmitting(true);

    try {
      await apiFetch("/api/reviews", {
        method: "POST",
        body: JSON.stringify(payload),
      });

      setSelectedRoomId(String(formRoomId));
      setSearch("");
      setRatingFilter("all");
      setSort("newest");
      setVisibleCount(PAGE_SIZE);
      setFormMessage("ส่งความคิดเห็นสำเร็จ ขอบคุณสำหรับข้อเสนอแนะ!");

      // โหลดรีวิวล่าสุดจาก Backend
      const result = await apiFetch(
        `/api/reviews?room_id=${encodeURIComponent(formRoomId)}`
      );

      setReviews(
        getArray(result, "reviews").map(normalizeReview)
      );

      window.setTimeout(() => {
        setModalOpen(false);
        setFormMessage("");
      }, 900);
    } catch (error) {
      setFormMessage(`ส่งความคิดเห็นไม่สำเร็จ: ${error.message}`);
    } finally {
      setSubmitting(false);
    }
  }

  // ----------------------------------------
  // PROFILE AND LOGOUT
  // ----------------------------------------

  const profileName =
    user?.displayname_th ||
    user?.displayname_en ||
    user?.username ||
    "PROFILE";

  function logout() {
    localStorage.removeItem("user");
    localStorage.removeItem("token");
    navigate("/");
  }

  // ----------------------------------------
  // DATE FORMAT
  // ----------------------------------------

  function formatDate(value) {
    if (!value) return "ไม่ระบุวันที่";

    const date = new Date(value);

    if (Number.isNaN(date.getTime())) {
      return String(value);
    }

    return new Intl.DateTimeFormat("th-TH", {
      day: "numeric",
      month: "short",
      year: "numeric",
    }).format(date);
  }

  function typeLabel(type) {
    const labels = {
      review: "รีวิวการใช้งาน",
      suggestion: "ข้อเสนอแนะ",
      problem: "แจ้งปัญหา",
    };

    return labels[type] || type;
  }

  // ----------------------------------------
  // RENDER
  // ----------------------------------------

  return (
    <div className="review-page">
      {/* NAVBAR */}
      <nav className="navbar">
        <div
          className="navbar-logo"
          onClick={() => navigate("/homepage")}
          role="button"
          tabIndex={0}
        >
          <img
            src={`${process.env.PUBLIC_URL}/logo.png`}
            alt="Booking CSTU Logo"
          />
        </div>

        <div className="navbar-links">
          <button onClick={() => navigate("/homepage")}>
            HOME
          </button>

          <button onClick={() => navigate("/mybooking")}>
            MY BOOKING
          </button>

          <button onClick={() => navigate("/Guide.html")}>
            GUIDE
          </button>

          <button onClick={() => navigate("/Rule.html")}>
            RULE
          </button>

          <button
            className="active"
            onClick={() => navigate("/review")}
          >
            REVIEW
          </button>

          <div className="profile-wrapper">
            <button
              className="profile-button"
              onClick={() => setProfileOpen((open) => !open)}
              aria-expanded={profileOpen}
            >
              PROFILE
            </button>

            {profileOpen && (
              <div className="profile-menu">
                <strong>{profileName}</strong>
                <p>{user?.email || ""}</p>
                <button onClick={logout}>ออกจากระบบ</button>
              </div>
            )}
          </div>
        </div>
      </nav>

      {/* HERO */}
      <header className="review-hero">
        <div className="review-hero-content">
          <p className="review-eyebrow">BOOKING CSTU</p>
          <h1>REVIEWS & FEEDBACK</h1>
          <p>
            รีวิวและแบ่งปันความคิดเห็นเพื่อพัฒนาการใช้งานห้อง
          </p>
        </div>
      </header>

      <main className="review-content">
        {/* ROOM SELECTOR */}
        <section className="review-toolbar">
          <div className="review-room-picker">
            <label htmlFor="roomSelect">เลือกห้องที่ต้องการดูรีวิว</label>

            <select
              id="roomSelect"
              value={selectedRoomId}
              onChange={(event) => {
                setSelectedRoomId(event.target.value);
                setFormRoomId(event.target.value);
                setVisibleCount(PAGE_SIZE);
              }}
            >
              <option value="">เลือกห้อง</option>

              {rooms.map((room) => (
                <option key={room.id} value={room.id}>
                  {room.name}
                </option>
              ))}
            </select>
          </div>

          <button
            type="button"
            className="review-refresh-button"
            onClick={refreshData}
            disabled={loading}
          >
            {loading ? "กำลังโหลด..." : "รีเฟรชข้อมูล"}
          </button>
        </section>

        {statusMessage && (
          <div className="review-status-message" role="status">
            {statusMessage}
          </div>
        )}

        {/* STATISTICS */}
        <section className="review-summary">
          <article className="review-summary-card">
            <span>คะแนนเฉลี่ย</span>
            <strong>
              {averageRating === null ? "—" : averageRating.toFixed(1)}
            </strong>
            <span className="review-summary-stars">
              {averageRating === null
                ? "☆☆☆☆☆"
                : "★".repeat(Math.round(averageRating)) +
                  "☆".repeat(5 - Math.round(averageRating))}
            </span>
            <small>
              {validRatings.length.toLocaleString("th-TH")} รีวิวที่มีคะแนน
            </small>
          </article>

          <article className="review-summary-card">
            <span>จำนวนผู้ใช้งานห้อง</span>
            <strong>
              {usageCount === null
                ? "—"
                : usageCount.toLocaleString("th-TH")}
            </strong>
            <small>จำนวนครั้งการใช้งานตามข้อมูล Backend</small>
          </article>

          <article className="review-summary-card">
            <span>จำนวนรีวิว</span>
            <strong>{reviews.length.toLocaleString("th-TH")}</strong>
            <small>{selectedRoom?.name || "กรุณาเลือกห้อง"}</small>
          </article>
        </section>

        {/* REVIEWS */}
        <section className="review-list-section">
          <div className="review-list-heading">
            <div>
              <h2>รีวิวการใช้งาน</h2>
              <p>
                {selectedRoom
                  ? `รีวิวของ ${selectedRoom.name}`
                  : "เลือกห้องเพื่อดูรีวิว"}
              </p>
            </div>

            <div className="review-action-buttons">
              <button
                type="button"
                className="review-primary-button"
                onClick={() => openModal("review")}
                disabled={!rooms.length}
              >
                เขียนรีวิว
              </button>

              <button
                type="button"
                className="review-secondary-button"
                onClick={() => openModal("suggestion")}
                disabled={!rooms.length}
              >
                ส่งข้อเสนอแนะ
              </button>
            </div>
          </div>

          <div className="review-filters">
            <input
              type="search"
              placeholder="ค้นหาชื่อหรือความคิดเห็น..."
              value={search}
              onChange={(event) => {
                setSearch(event.target.value);
                setVisibleCount(PAGE_SIZE);
              }}
            />

            <select
              value={ratingFilter}
              onChange={(event) => {
                setRatingFilter(event.target.value);
                setVisibleCount(PAGE_SIZE);
              }}
              aria-label="กรองตามคะแนน"
            >
              <option value="all">ทุกคะแนน</option>
              <option value="5">5 ดาว</option>
              <option value="4">4 ดาว</option>
              <option value="3">3 ดาว</option>
              <option value="2">2 ดาว</option>
              <option value="1">1 ดาว</option>
            </select>

            <select
              value={sort}
              onChange={(event) => {
                setSort(event.target.value);
                setVisibleCount(PAGE_SIZE);
              }}
              aria-label="เรียงลำดับรีวิว"
            >
              <option value="newest">ใหม่ล่าสุด</option>
              <option value="highest">คะแนนสูงสุด</option>
              <option value="lowest">คะแนนต่ำสุด</option>
            </select>
          </div>

          {loading && (
            <p className="review-loading">กำลังโหลดข้อมูล...</p>
          )}

          {!loading && filteredReviews.length === 0 && (
            <div className="review-empty-state">
              {!selectedRoomId
                ? "กรุณาเลือกห้องเพื่อดูรีวิว"
                : "ยังไม่มีรีวิวที่ตรงกับเงื่อนไขนี้"}
            </div>
          )}

          <div className="review-cards">
            {visibleReviews.map((review, index) => (
              <article
                className="review-card"
                key={review.id || `${review.name}-${review.date}-${index}`}
              >
                <div className="review-card-top">
                  <div className="reviewer-avatar">
                    {review.name.trim().charAt(0).toUpperCase() || "U"}
                  </div>

                  <div className="reviewer-details">
                    <strong>{review.name}</strong>
                    <span>{formatDate(review.date)}</span>
                  </div>

                  <span className="review-card-rating">
                    {review.rating
                      ? "★".repeat(review.rating) +
                        "☆".repeat(5 - review.rating)
                      : "ไม่ให้คะแนน"}
                  </span>
                </div>

                <span className="review-type">
                  {typeLabel(review.type)}
                </span>

                <p className="review-card-message">
                  {review.message || "ไม่มีรายละเอียด"}
                </p>
              </article>
            ))}
          </div>

          {filteredReviews.length > visibleReviews.length && (
            <div className="review-load-more-wrapper">
              <button
                type="button"
                className="review-secondary-button"
                onClick={() =>
                  setVisibleCount((count) => count + PAGE_SIZE)
                }
              >
                โหลดรีวิวเพิ่มเติม
              </button>
            </div>
          )}
        </section>
      </main>

      {/* REVIEW MODAL */}
      {modalOpen && (
        <div
          className="review-modal-overlay"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) closeModal();
          }}
        >
          <section
            className="review-modal"
            role="dialog"
            aria-modal="true"
            aria-labelledby="reviewModalTitle"
          >
            <div className="review-modal-header">
              <div>
                <h2 id="reviewModalTitle">
                  {feedbackType === "review"
                    ? "เขียนรีวิว"
                    : "ส่งข้อเสนอแนะ"}
                </h2>
                <p>ความคิดเห็นของคุณช่วยพัฒนาระบบ Booking CSTU</p>
              </div>

              <button
                type="button"
                className="review-modal-close"
                onClick={closeModal}
                disabled={submitting}
                aria-label="ปิด"
              >
                ×
              </button>
            </div>

            <form onSubmit={submitReview}>
              <div className="review-form-field">
                <label htmlFor="formRoomSelect">ห้อง</label>

                <select
                  id="formRoomSelect"
                  value={formRoomId}
                  onChange={(event) => setFormRoomId(event.target.value)}
                  required
                >
                  <option value="">เลือกห้อง</option>
                  {rooms.map((room) => (
                    <option key={room.id} value={room.id}>
                      {room.name}
                    </option>
                  ))}
                </select>
              </div>

              <div className="review-form-field">
                <label htmlFor="feedbackType">ประเภทความคิดเห็น</label>

                <select
                  id="feedbackType"
                  value={feedbackType}
                  onChange={(event) => {
                    setFeedbackType(event.target.value);
                    setRating(0);
                    setFormMessage("");
                  }}
                >
                  <option value="review">รีวิวการใช้งาน</option>
                  <option value="suggestion">ข้อเสนอแนะ</option>
                  <option value="problem">แจ้งปัญหา</option>
                </select>
              </div>

              {feedbackType === "review" && (
                <div className="review-form-field">
                  <label>คะแนนรีวิว</label>

                  <div className="review-star-picker">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <button
                        key={star}
                        type="button"
                        className={star <= rating ? "selected" : ""}
                        onClick={() => setRating(star)}
                        aria-label={`${star} ดาว`}
                        aria-pressed={rating === star}
                      >
                        ★
                      </button>
                    ))}
                  </div>

                  <small>
                    {rating ? `คุณให้ ${rating} จาก 5 ดาว` : "เลือกคะแนน 1–5 ดาว"}
                  </small>
                </div>
              )}

              <div className="review-form-field">
                <label htmlFor="reviewMessage">รายละเอียด</label>

                <textarea
                  id="reviewMessage"
                  value={comment}
                  onChange={(event) => setComment(event.target.value)}
                  placeholder="แบ่งปันความคิดเห็นของคุณ..."
                  rows={5}
                  maxLength={2000}
                  required
                />
              </div>

              {formMessage && (
                <p
                  className={`review-form-message ${
                    formMessage.includes("สำเร็จ") ? "success" : ""
                  }`}
                  role="status"
                >
                  {formMessage}
                </p>
              )}

              <div className="review-modal-actions">
                <button
                  type="button"
                  className="review-cancel-button"
                  onClick={closeModal}
                  disabled={submitting}
                >
                  ยกเลิก
                </button>

                <button
                  type="submit"
                  className="review-primary-button"
                  disabled={submitting}
                >
                  {submitting ? "กำลังส่ง..." : "ส่งความคิดเห็น"}
                </button>
              </div>
            </form>
          </section>
        </div>
      )}
    </div>
  );
}
